schemas:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [

    {
      "@type": "Question",
      "name": "هل يجب تسجيل جهاز الكاشير لدى مصلحة الضرائب المصرية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم. الجهاز غير المدرج في قائمة الموردين المعتمدين لا يُصدر إيصالًا إلكترونيًا معتمدًا، ويعرّض المحل لمخالفات."
      }
    },

    {
      "@type": "Question",
      "name": "ما الفرق بين الورق الحراري بعرض 57 مم و80 مم؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "عرض 57 مم مناسب للطابعات الصغيرة والفواتير قصيرة البنود. عرض 80 مم هو القياس الشائع لطابعات التجزئة والمطاعم لأنه يستوعب فواتير أطول مع طباعة أوضح."
      }
    },

    {
      "@type": "Question",
      "name": "ما العوامل الرئيسية التي ترفع تكلفة تجهيز منظومة نقطة البيع؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الاتصال اللاسلكي بدلًا من USB، وإضافة شاشة عرض للعميل، وجهاز جرد متنقل، وميزان باركود مدمج، وعقد صيانة بزمن استجابة قصير مكتوب بوضوح."
      }
    },

    {
      "@type": "Question",
      "name": "هل يمكن استخدام ورق حراري من أي مورّد في طابعة الكاشير؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "لا يُنصح بذلك. الورق غير المطابق يُجبر الرأس على العمل بحرارة أعلى ويقصّر عمرها."
      }
    },

    {
      "@type": "Question",
      "name": "ما الفرق بين قارئ الباركود أحادي البعد وثنائي البعد؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "القارئ أحادي البعد (1D) يقرأ الأكواد الخطية التقليدية فقط، بينما ثنائي البعد (2D) يقرأ إضافة إليها رموز QR والباركود ثنائي البعد."
      }
    },

    {
      "@type": "Question",
      "name": "كيف يؤثر نوع الاتصال في التكلفة؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "USB يخفض تكلفة الوحدة والإعداد ويقلل نقاط الفشل. اللاسلكي يرفع تكلفة كل وحدة ويحتاج شبكة موثوقة."
      }
    }

  ]
}
